parameters.jsCode:
// One item per payment that is worth a model call.
//
// Two reasons an item is skipped here rather than in the workflow's
// branching: a missing screenshot has nothing to read, and a payment
// that already has a previous `pass` was approved by an earlier run —
// re-reading it costs a vision call to confirm what the payment row no
// longer has status proof_submitted for.
//
// THE PROMPT LIVES HERE, not in an env var, and it is deliberately blind:
// it never receives the expected amount or authorization number. A reader
// shown the answer will agree with the answer. The comparison happens on
// the server against `expected`, which this item carries but the model
// never sees — see the `Read the screenshot` node, which sends only
// `screenshot`.
const queue = $input.first().json;
if (!queue || !Array.isArray(queue.items)) {
  throw new Error('queue response had no items array — check the token and the portal URL');
}

const PROMPT = [
  'You read Tunisian D17 (La Poste) money-transfer receipts from a photograph.',
  'Your only job is to report what is PRINTED. You never decide whether a payment is valid.',
  '',
  'Return ONLY a JSON object, no prose and no code fences, with exactly these keys:',
  '{"amount": string|null, "authNumber": string|null, "senderPhone": string|null, "receiverPhone": string|null, "date": string|null}',
  '',
  'Rules:',
  '- NEVER guess a digit. If a character is blurry, cropped, or glare-obscured, return null for that field.',
  '- amount: the transferred AMOUNT ONLY, as printed, with its decimal separator. Do not add a currency word.',
  '  Do not return a fee, a balance, or a total-sum line unless it is the amount sent.',
  '- authNumber: the authorization / transaction / reference number exactly as printed, no spaces added.',
  '  In the official D17 app receipt it appears under "Numero d\'autorisation" and is usually 6 digits.',
  '',
  'THE OFFICIAL D17 APP LAYOUT (La Poste Tunisienne), which is what most customers will send:',
  '  A blue card. A diamond logo reading "LA POSTE TUNISIENNE" / "البريد التونسي" at the top.',
  '  Then, in order, as labelled rows:',
  '    "Operation D17"            followed by a timestamp, e.g. 12/11/2026 19:14:44',
  '    "Service"                  e.g. "Transfert vers 29293037"  <- that number is the RECEIVER',
  '    "Montant"                  e.g. "-100,000 TND"  <- NEGATIVE and comma-decimal',
  '    "Numero d\'autorisation"   e.g. "244650"',
  '  Notes for this layout:',
  '  - The amount is printed NEGATIVE and with a COMMA decimal separator. Report it as',
  '    printed ("-100,000"); the debit sign is how D17 shows money leaving the sender.',
  '  - There is NO sender phone on this layout. Return senderPhone as null — do not',
  '    invent one, and do not substitute the receiver number.',
  '  - senderPhone comes only from layouts that print "TELEPHONE EXPEDITEUR".',
  '  - The receiver is the number after "Transfert vers"; report it as digits only.',
  '  - The date is the timestamp next to "Operation D17", not a separate DATE row.',
  '- senderPhone: the phone number of the sender (the payer), digits only, no country code formatting.',
  '- receiverPhone: the phone number of the recipient (the payee).',
  '- date: the transfer date and time in ISO 8601. If only a date is printed, return YYYY-MM-DD.',
  '- If the image is not a payment receipt, return every field as null.',
  '- If two numbers could be the authorization number, return null rather than pick one.',
].join('\n');

const work = queue.items.filter(
  (it) => it.screenshot && !(it.previous && it.previous.verdict === 'pass'),
);

if (work.length === 0) {
  return [];
}

return work.map((it) => ({ json: { ...it, prompt: PROMPT } }));

parameters.jsonBody:
={{ JSON.stringify({
  model: 'smart',
  max_tokens: 2048,
  temperature: 0,
  system: $json.prompt,
  messages: [
    {
      role: 'user',
      content: [
        {
          type: 'image',
          source: {
            type: 'base64',
            media_type: 'image/png',
            data: $json.screenshot,
          },
        },
        {
          type: 'text',
          text: 'Read this receipt and return only the JSON object described in your instructions.',
        },
      ],
    },
  ],
}) }}

parameters.jsCode:
// Turn the model's reply into the reading the portal expects.
//
// This node does NOT decide anything. It extracts fields. Every judgement
// — is the amount right, is the number right, does it pass — happens in
// `scoreVerification()` on the server, deliberately, so that a bug in
// this node can mislabel a field but cannot approve a payment.
//
// A model that returns prose, a refusal, or malformed JSON yields a
// reading with every field null, which the server scores as `review`.
// Silently dropping the item would leave the payment stuck with no
// evidence row at all, which is strictly worse for staff.
const payment = $('Pick unread proofs').item.json;
const res = $input.first().json;

if (res.error || typeof res !== 'object' || !Array.isArray(res.content)) {
  return [{ json: {
    paymentId: payment.paymentId,
    extracted: { amount: null, authNumber: null, senderPhone: null, receiverPhone: null, date: null },
    model: 'smart',
    inputTokens: null,
    outputTokens: null,
    readerError: res.error ? JSON.stringify(res.error).slice(0, 300) : 'no content array',
  } }];
}

const text = res.content
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('\n')
  .trim();

// Models wrap JSON in fences often enough that strip-before-parse is the
// difference between "works" and "works half the time".
const unfenced = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

let parsed = {};
const start = unfenced.indexOf('{');
const end = unfenced.lastIndexOf('}');
if (start !== -1 && end > start) {
  try {
    parsed = JSON.parse(unfenced.slice(start, end + 1));
  } catch {
    parsed = {};
  }
}

// A reply that stopped because it ran out of tokens ends mid-object. The
// parse above can still succeed on the fields it reached, which turns a
// truncated transcription into a plausible-looking WRONG number — the
// single worst thing this pipeline can produce. `stop_reason` is the
truth, so trust it over the parse.
const truncated = res.stop_reason === 'max_tokens';

const str = (v) =>
  truncated ? null : typeof v === 'string' && v.trim() ? v.trim() : null;

return [{ json: {
  paymentId: payment.paymentId,
  extracted: {
    amount: str(parsed.amount),
    authNumber: str(parsed.authNumber),
    senderPhone: str(parsed.senderPhone),
    receiverPhone: str(parsed.receiverPhone),
    date: str(parsed.date),
  },
  model: res.model || 'smart',
  inputTokens: res.usage?.input_tokens ?? null,
  outputTokens: res.usage?.output_tokens ?? null,
  readerError: null,
} }];

