parameters.jsCode:
// Summarise the batch into one line for the run log.
//
// Nothing notifies a human from here: a `review` is already visible in
// the admin queue, and a `fail` already sits there with a reason. Paging
// on every blurry screenshot would train staff to ignore the page.
const results = $input.all().map((i) => i.json);
const approved = results.filter((r) => r.approved === true).length;
const review = results.filter((r) => r.verdict === 'review').length;
const failed = results.filter((r) => r.verdict === 'fail').length;
const errored = results.filter((r) => r.error || r.code).length;

return [{ json: {
  processed: results.length,
  approved,
  review,
  failed,
  errored,
  at: new Date().toISOString(),
  detail: results.map((r) => ({
    paymentId: r.paymentId ?? null,
    verdict: r.verdict ?? null,
    score: r.score ?? null,
    approved: r.approved ?? false,
    blockedBy: r.blockedBy ?? r.code ?? null,
  })),
} }];
